package com.healthwise.timeline.service;import com.healthwise.analysis.repository.AnalysisHistoryRepository;import com.healthwise.questionnaire.repository.QuestionnaireRepository;import com.healthwise.recommendation.repository.RecommendationRepository;import com.healthwise.report.repository.ReportRepository;import com.healthwise.timeline.dto.TimelineEvent;import java.util.*;import org.springframework.stereotype.Service;
/** Builds user timeline from MongoDB collections. */@Service public class TimelineService{private final QuestionnaireRepository q;private final RecommendationRepository r;private final ReportRepository reports;private final AnalysisHistoryRepository a;public TimelineService(QuestionnaireRepository q,RecommendationRepository r,ReportRepository p,AnalysisHistoryRepository a){this.q=q;this.r=r;reports=p;this.a=a;}public List<TimelineEvent> timeline(String u){List<TimelineEvent> e=new ArrayList<>();q.findByUserIdOrderBySubmittedAtDesc(u).forEach(x->e.add(new TimelineEvent("QUESTIONNAIRE",x.getSubmittedAt(),"Questionnaire Submitted","Health questionnaire submitted")));r.findByUserIdOrderByGeneratedAtDesc(u).forEach(x->e.add(new TimelineEvent("RECOMMENDATION",x.getGeneratedAt(),"Recommendation Generated","Laboratory recommendations saved")));reports.findByUserIdOrderByUploadedAtDesc(u).forEach(x->e.add(new TimelineEvent("REPORT",x.getUploadedAt(),"Report Uploaded",x.getReportName())));a.findByUserIdOrderByAnalyzedAtDesc(u).forEach(x->e.add(new TimelineEvent("ANALYSIS",x.getAnalyzedAt(),"Analysis Completed","AI report analysis saved")));return e.stream().sorted(Comparator.comparing(TimelineEvent::timestamp).reversed()).toList();}}
